function yourFunction(params) {

  const persons = params.allPerson || [];
  const requiredEmail = (params.requiredPersonEmail || "").toLowerCase();

  for (const person of persons) {
    const emails = person.item?.emails || [];

    for (const email of emails) {
      if (email.toLowerCase() === requiredEmail) {
        return {
          result: {
            personID: person.item.id,
            exists: true
          }
        };
      }
    }
  }

  return {
    result: {
      exists: false
    }
  };
}

