function yourFunction(params) {
  const persons = params.persons || [];
  const email = (params.email || "").toLowerCase();

  for (const p of persons) {

    const item = p.item || p; // handles both structures
    const emails = item.emails || [];

    const match = emails.some(e => {
      if (typeof e === "string") {
        return e.toLowerCase() === email;
      }
      if (e && e.value) {
        return e.value.toLowerCase() === email;
      }
      return false;
    });

    if (match) {
      return {
        person_id: item.id
      };
    }
  }

  return {
    person_id: null
  };
}
